import os
root='.'
files=[]
for d, dirs, names in os.walk(root):
    for name in names:
        p=os.path.join(d,name)
        try:
            if os.path.isfile(p): files.append((os.path.getsize(p), os.path.relpath(p, root)))
        except OSError: pass
for size,path in sorted(files, reverse=True)[:30]: print(f'{size:>15,} bytes  {path}')
